// Values-only Boolean polynomials. Opaque atoms widen possibilities; they never
// supply a known bit. Equal structural expressions may share an opaque atom.
use super::{Program,TV,QX,QCX,QCCX,QSWAP,QZERO,CINV,CZERO,CONE,CRNG};
use std::collections::{BTreeMap,HashMap};
#[derive(Clone,Default,Debug,PartialEq,Eq,Hash)]struct Poly(Vec<(u32,u64)>);
impl Poly{fn known(v:u64)->Self{Self(if v==0{vec![]}else{vec![(0,v)]})}fn constant(&self)->Option<u64>{if self.0.is_empty(){Some(0)}else if self.0.len()==1&&self.0[0].0==0{Some(self.0[0].1)}else{None}}fn tv(&self)->TV{let mut c=0;let mut unknown=0;for &(m,v)in &self.0{if m==0{c=v;}else{unknown|=v;}}TV{z:!c&!unknown,o:c&!unknown}}}
struct Algebra{monos:Vec<Vec<u32>>,truth:Vec<u64>,products:HashMap<Vec<u32>,u32>,opaque:HashMap<Poly,u32>}
impl Algebra{
 fn new()->Self{Self{monos:vec![vec![]],truth:vec![u64::MAX],products:HashMap::new(),opaque:HashMap::new()}}
 fn atom(&mut self,truth:u64)->u32{let id:u32=self.monos.len().try_into().unwrap();self.monos.push(vec![id]);self.truth.push(truth);id}
 fn value(&self,p:&Poly)->u64{p.0.iter().fold(0,|v,&(id,c)|v^(c&self.truth[id as usize]))}
 fn variable(&mut self,truth:u64)->Poly{Poly(vec![(self.atom(truth),u64::MAX)])}
 fn multiply_monomial(&mut self,a:u32,b:u32)->u32{if a==0{return b;}if b==0||a==b{return a;}let mut factors=self.monos[a as usize].clone();factors.extend_from_slice(&self.monos[b as usize]);factors.sort_unstable();factors.dedup();if factors.len()==1{return factors[0];}if let Some(&id)=self.products.get(&factors){return id;}let truth=factors.iter().fold(u64::MAX,|v,&x|v&self.truth[x as usize]);let id:u32=self.monos.len().try_into().unwrap();self.monos.push(if factors.len()<=4{factors.clone()}else{vec![id]});self.truth.push(truth);if self.products.len()<65536{self.products.insert(factors,id);}id}
 fn bound(&mut self,p:Poly)->Poly{if p.0.len()<=8{return p;}let tv=p.tv();let mask=!(tv.z|tv.o);if mask==0{return Poly::known(tv.o);}let id=if let Some(&id)=self.opaque.get(&p){id}else{let truth=self.value(&p);let id=self.atom(truth);if self.opaque.len()<65536{self.opaque.insert(p,id);}id};let mut terms=vec![];if tv.o!=0{terms.push((0,tv.o));}terms.push((id,mask));Poly(terms)}
 fn xor(&mut self,a:&Poly,b:&Poly)->Poly{if a==b{return Poly::default();}let(mut i,mut j)=(0,0);let mut out=vec![];while i<a.0.len()||j<b.0.len(){if j==b.0.len()||(i<a.0.len()&&a.0[i].0<b.0[j].0){out.push(a.0[i]);i+=1;}else if i==a.0.len()||b.0[j].0<a.0[i].0{out.push(b.0[j]);j+=1;}else{let v=a.0[i].1^b.0[j].1;if v!=0{out.push((a.0[i].0,v));}i+=1;j+=1;}}self.bound(Poly(out))}
 fn not(&mut self,a:&Poly)->Poly{self.xor(a,&Poly::known(u64::MAX))}
 fn and(&mut self,a:&Poly,b:&Poly)->Poly{if a==b{return a.clone();}if let Some(v)=a.constant(){return Poly(b.0.iter().filter_map(|&(m,c)|{let x=c&v;(x!=0).then_some((m,x))}).collect());}if b.constant().is_some(){return self.and(b,a);}let mut out=BTreeMap::<u32,u64>::new();for &(am,av)in &a.0{for &(bm,bv)in &b.0{let c=av&bv;if c!=0{let m=self.multiply_monomial(am,bm);*out.entry(m).or_default()^=c;}}}self.bound(Poly(out.into_iter().filter(|(_,v)|*v!=0).collect()))}
 fn ite(&mut self,g:&Poly,a:&Poly,b:&Poly)->Poly{if a==b{return a.clone();}let x=self.xor(a,b);let y=self.and(g,&x);self.xor(b,&y)}
}
pub(super)fn eval(p:&Program,initial_q:&[u64],initial_bits:&[u64])->Vec<TV>{let mut alg=Algebra::new();let mut q:Vec<_>=initial_q.iter().map(|&v|Poly::known(v)).collect();let mut c=vec![Poly::default();p.versions];for(i,&v)in initial_bits.iter().enumerate(){c[i]=Poly::known(v);}let mut random=HashMap::new();for(i,n)in p.nodes.iter().enumerate(){if alg.monos.len()>16_000_000{eprintln!("AFFINE_BUDGET_EXHAUSTED at={i} sound_TV_continuation");return finish(p,i,q.iter().map(Poly::tv).collect(),c.iter().map(Poly::tv).collect());}if i%1000000==0{eprintln!("AFFINE_PROGRESS nodes={i} monomials={} product_cache={} opaque_cache={}",alg.monos.len(),alg.products.len(),alg.opaque.len());}let mut g=Poly::known(u64::MAX);for &v in &p.guards[n.g as usize]{g=alg.and(&g,&c[v as usize]);}let t=n.t as usize;match n.k{
 QX=>q[t]=alg.xor(&q[t],&g),QCX=>{let x=alg.and(&g,&q[n.a as usize]);q[t]=alg.xor(&q[t],&x);},QCCX=>{let a=alg.and(&g,&q[n.a as usize]);let x=alg.and(&a,&q[n.b as usize]);q[t]=alg.xor(&q[t],&x);},QSWAP=>{let a=n.a as usize;let x=alg.xor(&q[a],&q[t]);let x=alg.and(&g,&x);q[a]=alg.xor(&q[a],&x);q[t]=alg.xor(&q[t],&x);},QZERO=>{let ng=alg.not(&g);q[t]=alg.and(&q[t],&ng);},CINV=>c[t]=alg.xor(&c[n.a as usize],&g),CZERO=>{let ng=alg.not(&g);c[t]=alg.and(&c[n.a as usize],&ng);},CONE=>c[t]=alg.ite(&g,&Poly::known(u64::MAX),&c[n.a as usize]),CRNG=>{let id=*random.entry(n.r).or_insert_with(||alg.atom(0));let fresh=Poly(vec![(id,u64::MAX)]);c[t]=alg.ite(&g,&fresh,&c[n.a as usize]);},_=>unreachable!()}}
 eprintln!("AFFINE_COMPLETE monomials={} product_cache={} opaque_cache={}",alg.monos.len(),alg.products.len(),alg.opaque.len());q.iter().map(Poly::tv).collect()}
fn finish(p:&Program,at:usize,mut q:Vec<TV>,mut c:Vec<TV>)->Vec<TV>{for n in &p.nodes[at..]{let g=p.guards[n.g as usize].iter().fold(TV::known(u64::MAX),|v,&x|v.and(c[x as usize]));let t=n.t as usize;match n.k{QX=>q[t]=q[t].xor(g),QCX=>q[t]=q[t].xor(g.and(q[n.a as usize])),QCCX=>q[t]=q[t].xor(g.and(q[n.a as usize]).and(q[n.b as usize])),QSWAP=>{let old=q[t];q[t]=g.ite(q[n.a as usize],old);q[n.a as usize]=g.ite(old,q[n.a as usize]);},QZERO=>q[t]=q[t].and(g.not()),CINV=>c[t]=c[n.a as usize].xor(g),CZERO=>c[t]=c[n.a as usize].and(g.not()),CONE=>c[t]=c[n.a as usize].or(g),CRNG=>c[t]=g.ite(TV::unknown(),c[n.a as usize]),_=>unreachable!()}}q}
#[cfg(test)]mod tests{use super::*;
 #[test]fn bounded_polynomials_preserve_exact_values_and_known_bits_for_all_six_variable_assignments(){let mut alg=Algebra::new();let mut values:Vec<Poly>=(0..6).map(|bit|{let mut v=0;for lane in 0..64{v|=(((lane>>bit)&1)as u64)<<lane;}alg.variable(v)}).collect();values.push(Poly::known(0x3c0fa55a1e9678b4));let mut seed=0x28fa773ce6130091u64;for _ in 0..1000{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);let a=values[(seed as usize)%values.len()].clone();let b=values[((seed>>17)as usize)%values.len()].clone();let g=values[((seed>>33)as usize)%values.len()].clone();let av=alg.value(&a);let bv=alg.value(&b);let gv=alg.value(&g);let(p,expected)=match seed%4{0=>(alg.xor(&a,&b),av^bv),1=>(alg.and(&a,&b),av&bv),2=>(alg.not(&a),!av),_=>(alg.ite(&g,&a,&b),(gv&av)|(!gv&bv))};assert_eq!(alg.value(&p),expected);let tv=p.tv();assert_eq!(tv.z&tv.o,0);assert_eq!(expected&(tv.z|tv.o),tv.o);assert!(p.0.len()<=8);if values.len()<64{values.push(p);}else{let index=((seed>>8)as usize)%64;values[index]=p;}}}
 #[test]fn correlated_unknowns_cancel_without_assuming_any_random_value(){let mut alg=Algebra::new();let a=alg.variable(0xa55a33ccf00f1701);let b=alg.variable(0x1f0e4d3caabbee99);assert_eq!(alg.xor(&a,&a),Poly::known(0));let na=alg.not(&a);assert_eq!(alg.xor(&a,&na),Poly::known(u64::MAX));let x=alg.and(&a,&b);let y=alg.and(&b,&a);assert_eq!(alg.xor(&x,&y),Poly::known(0));assert_eq!(a.tv().z|a.tv().o,0);let mut terms=vec![(0,0xff00)];for _ in 0..12{terms.push((alg.atom(u64::MAX),0x00ff));}let p=alg.bound(Poly(terms));assert_eq!(p.tv().z|p.tv().o,!0x00ffu64);assert_eq!(p.tv().o,0xff00);}
 #[test]fn budget_fallback_is_the_same_sound_three_valued_machine(){use quantum_ecc::circuit::{Op,OperationType as K,QubitId,BitId};let mut x=Op::empty();x.kind=K::X;x.q_target=QubitId(0);x.c_condition=BitId(0);let mut h=Op::empty();h.kind=K::Hmr;h.q_target=QubitId(1);h.c_target=BitId(1);let mut y=x;y.c_condition=BitId(1);let ops=vec![x,h,y];let p=super::super::compile(&ops,&[0]);let q=vec![0;p.nq];let bits=vec![0;p.nb];let expected=super::super::abstract_eval(&p,&q,&bits);let mut c=vec![TV::unknown();p.versions];for(i,&b)in bits.iter().enumerate(){c[i]=TV::known(b);}let actual=finish(&p,0,q.iter().map(|&v|TV::known(v)).collect(),c);for(a,b)in actual.iter().zip(expected){assert_eq!((a.z,a.o),(b.z,b.o));}}

}
